type Four<T> = readonly [T, T, T, T];
type Three<T> = readonly [T, T, T];
type Cue = readonly [value: string, firstLine: string, secondLine: string];

export interface CapabilitySlide {
  title: string;
  desc: string;
  list: Three<string>;
  imageAlt: string;
}
export interface LeftColumnContent {
  badge: string;
  heading: readonly [string, string];
  intro: string;
  body: string;
  cta: string;
  cues: Three<Cue>;
  slides: Four<CapabilitySlide>;
}

const slide = (title: string, desc: string, list: Three<string>, context: string): CapabilitySlide => ({ title, desc, list, imageAlt: `Existing software-dashboard illustration accompanying ${context}` });
const carousel = (badge: string, heading: readonly [string, string], intro: string, body: string, cta: string, cues: Three<Cue>, slides: Four<CapabilitySlide>): LeftColumnContent => ({ badge, heading, intro, body, cta, cues, slides });

