export function getLeftColumnContent(path?: string | null): LeftColumnContent {
  const clean = (path || "/").split(/[?#]/, 1)[0].trim().toLowerCase().replace(/^\/+|\/+$/g, "");
  return leftColumnContent[clean ? `/${clean}/` : "/"] || fallbackLeftColumn;
}
